using System.Collections.Frozen;
using System.Reflection;

namespace Plus.HabboHotel.Items;

/// <summary>
/// The directions each floor furni has, as the client knows them: logic.model.directions in its .hab asset.
/// The table is FurnitureDirections.tsv, generated by scripts/build-furniture-directions.py. Values are in wired units
/// (degrees / 45), sorted. A furni missing from the table keeps the old rule: even directions, odd ones only with extra_rot.
/// </summary>
public static class FurnitureDirections
{
    private const string Resource = "Plus.Items.FurnitureDirections.tsv";
    private static readonly Lazy<FrozenDictionary<string, int[]>> Table = new(Load);

    /// <summary>The directions of a classname; colour variants ("name*3") share their base asset. Empty when unknown.</summary>
    public static IReadOnlyList<int> For(string? itemName)
    {
        if (string.IsNullOrEmpty(itemName)) {
            return [];
        }

        var star = itemName.IndexOf('*');

        return Table.Value.TryGetValue(star < 0 ? itemName : itemName[..star], out var directions) ? directions : [];
    }

    /// <summary>Whether the furni may face a rotation: one of its directions, or an even one (odd with extra_rot) as before.</summary>
    public static bool Allows(ItemDefinition definition, int rotation) =>
        rotation is >= 0 and <= 7 && (definition.Directions.Contains(rotation) || definition.ExtraRot || rotation % 2 == 0);

    /// <summary>
    /// The rotation a projectile furni lands on, or null when it keeps its rotation. A heading the furni lacks lands it on its
    /// furnidata defaultdir. A heading the furni has is taken as it is.
    /// </summary>
    public static int? Heading(ItemDefinition definition, int heading)
    {
        heading = (heading % 8 + 8) % 8;
        var directions = definition.Directions;

        if (directions.Count == 0) {
            return Allows(definition, heading) ? heading : null;
        }

        if (directions.Contains(heading)) {
            return heading;
        }

        return directions.Contains(definition.DefaultDirection) ? definition.DefaultDirection : null;
    }

    /// <summary>
    /// The next direction the furni has clockwise or counterclockwise in 45 degree order, the step the client's rotate takes.
    /// </summary>
    public static int Turn(ItemDefinition definition, int rotation, bool clockwise)
    {
        var directions = definition.Directions;

        if (directions.Count == 0) {
            return (rotation + (clockwise ? 2 : 6)) % 8;
        }

        // Like the client, a rotation the furni lacks counts as the direction at or after it.
        var index = IndexAtOrAfter(directions, rotation);

        return directions[clockwise ? (index + 1) % directions.Count : (index - 1 + directions.Count) % directions.Count];
    }

    /// <summary>
    /// The rotation a snapshot match stores, or null to leave the furni as it is. A value the furni lacks becomes the nearest
    /// direction within 45 degrees, clockwise first; anything further is refused. (@rotation writes a position in the list instead,
    /// see <see cref="RotationAt"/>.)
    /// </summary>
    public static int? Write(ItemDefinition definition, int value)
    {
        if (value is < 0 or > 7) {
            return null;
        }

        var directions = definition.Directions;

        if (directions.Count == 0) {
            return Allows(definition, value) ? value : null;
        }

        foreach (var candidate in new[] { value, (value + 1) % 8, (value + 7) % 8 }) {
            if (directions.Contains(candidate)) {
                return candidate;
            }
        }

        return null;
    }

    /// <summary>
    /// The rotation a user's move or placement stores: a direction the furni lacks becomes its furnidata defaultdir (or its first
    /// direction when defaultdir is not one of them). Furni without asset directions keep the old rule.
    /// </summary>
    public static int Place(ItemDefinition definition, int rotation)
    {
        var directions = definition.Directions;

        if (directions.Count == 0) {
            return rotation == 8 || Allows(definition, rotation) ? rotation : 0;
        }

        if (directions.Contains(rotation)) {
            return rotation;
        }

        return directions.Contains(definition.DefaultDirection) ? definition.DefaultDirection : directions[0];
    }

    /// <summary>
    /// The value @rotation reads: the position of the furni's rotation in its list of directions. Furni without asset directions count even directions, or all eight with extra_rot.
    /// </summary>
    public static int RotationIndex(ItemDefinition definition, int rotation)
    {
        var directions = WiredDirections(definition);
        var index = directions.IndexOf(rotation);

        return index >= 0 ? index : IndexAtOrAfter(directions, rotation);
    }

    /// <summary>
    /// The rotation an @rotation write stores, or null to leave the furni as it is: the direction at that position of the furni's
    /// list.
    /// </summary>
    public static int? RotationAt(ItemDefinition definition, int index)
    {
        var directions = WiredDirections(definition);

        return index >= 0 && index < directions.Count ? directions[index] : null;
    }

    private static List<int> WiredDirections(ItemDefinition definition) => definition.Directions.Count > 0 ? [.. definition.Directions]
        : definition.ExtraRot ? [0, 1, 2, 3, 4, 5, 6, 7] : [0, 2, 4, 6];

    // The first direction at or after a rotation, wrapping to the first direction.
    private static int IndexAtOrAfter(IReadOnlyList<int> directions, int rotation)
    {
        for (var index = 0; index < directions.Count; index++) {
            if (rotation <= directions[index]) {
                return index;
            }
        }

        return 0;
    }

    internal static FrozenDictionary<string, int[]> Parse(TextReader reader)
    {
        var table = new Dictionary<string, int[]>(StringComparer.Ordinal);

        while (reader.ReadLine() is { } line) {
            if (line.Length == 0 || line[0] == '#') {
                continue;
            }

            var tab = line.IndexOf('\t');

            if (tab <= 0) {
                continue;
            }

            var directions = line[(tab + 1)..].Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .Select(value => int.TryParse(value, out var direction) ? direction : -1)
                .Where(direction => direction is >= 0 and <= 7)
                .Distinct()
                .Order()
                .ToArray();

            if (directions.Length > 0) {
                table[line[..tab]] = directions;
            }
        }

        return table.ToFrozenDictionary(StringComparer.Ordinal);
    }

    private static FrozenDictionary<string, int[]> Load()
    {
        using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(Resource)
            ?? throw new InvalidOperationException($"Missing embedded resource {Resource}.");
        using var reader = new StreamReader(stream);

        return Parse(reader);
    }
}
